"""Read pre-Misong data without rewriting sessions or losing checkpoints."""
import asyncio
import hashlib
import json
import shutil
import sys
import zipfile
from pathlib import Path
from types import SimpleNamespace

import pytest

from misong import pack, split, workflows
from misong.cli import main
from misong.desktop.api import Api
from misong.jobs import fingerprint, save_json
from misong.rpa.runtime import DEFAULT_STATE, ROOT


def legacy_archive(folder, version):
    """Independent ZIP + old schema fixture, not generated by the renamed writer."""
    folder.mkdir(parents=True, exist_ok=True)
    payload = "旧版发布的内容，中文与 emoji 😀".encode()
    artifact = folder / "payload.zip"
    with zipfile.ZipFile(artifact, "w") as archive:
        archive.writestr("source.txt", payload)
    manifest = {"version": version, "artifact": artifact.name,
                "layers": [{"format": "zip", "password": False, "tar_pre": False,
                            "input_names": ["source.txt"]}]}
    if version == 2:
        manifest["layers"][0]["type"] = "archive"
        manifest["artifacts"] = [{"name": artifact.name, "size": artifact.stat().st_size,
                                  "sha256": hashlib.sha256(artifact.read_bytes()).hexdigest()}]
    sidecar = folder / "payload.zip.nde.json"
    save_json(sidecar, manifest)
    return artifact, sidecar, payload


def legacy_volumes(folder, data, base="payload.zip"):
    folder.mkdir(parents=True, exist_ok=True)
    parts = []
    for start in range(0, len(data), 50):
        chunk = data[start:start + 50]
        index = len(parts) + 1
        name = f"{base}.{index:03d}"
        (folder / name).write_bytes(chunk)
        parts.append({"name": name, "index": index, "size": len(chunk),
                      "sha256": hashlib.sha256(chunk).hexdigest()})
    manifest = {"version": 1, "source": base, "source_size": len(data),
                "source_sha256": hashlib.sha256(data).hexdigest(), "part_size": 50,
                "part_count": len(parts), "parts": parts}
    save_json(folder / (base + ".ndesplit.json"), manifest)
    return folder / parts[0]["name"], manifest


@pytest.mark.parametrize("version", [1, 2])
def test_legacy_manifest_restores_without_sniff_fallback(tmp_path, monkeypatch, version):
    artifact, sidecar, payload = legacy_archive(tmp_path / "old", version)
    original = sidecar.read_bytes()
    monkeypatch.setattr(pack.merge, "unwrap", lambda *a, **kw: pytest.fail("old manifest was ignored"))
    restored = pack.unest(artifact, tmp_path / "restore", [])
    assert restored[0].read_bytes() == payload
    assert sidecar.read_bytes() == original
    assert not artifact.with_name(artifact.name + ".misong.json").exists()


def test_legacy_v2_split_archive_restores_via_cli(tmp_path):
    artifact, sidecar, payload = legacy_archive(tmp_path / "old", 2)
    first, volume_manifest = legacy_volumes(artifact.parent, artifact.read_bytes())
    artifact.unlink()
    manifest = json.loads(sidecar.read_text(encoding="utf-8"))
    manifest["layers"].insert(0, {"type": "split", "split_manifest": volume_manifest})
    manifest["artifacts"] = volume_manifest["parts"]
    save_json(sidecar, manifest)
    assert main(["unest", str(first), "-o", str(tmp_path / "restore")]) == 0
    assert (tmp_path / "restore" / "source.txt").read_bytes() == payload


@pytest.mark.parametrize("damage", ["none", "corrupt", "missing"])
def test_legacy_split_sidecar_enforces_verification(tmp_path, damage):
    payload = bytes(range(256))
    first, manifest = legacy_volumes(tmp_path / "old", payload, "source.bin")
    assert split.has_verification(first)
    last = first.parent / manifest["parts"][-1]["name"]
    if damage == "corrupt":
        last.write_bytes(b"X" * last.stat().st_size)
    elif damage == "missing":
        last.unlink()
    out = tmp_path / "restored.bin"
    if damage == "none":
        assert split.join(first, out).read_bytes() == payload
    else:
        with pytest.raises(RuntimeError, match="校验失败"):
            split.join(first, out)
        assert not out.exists()


def test_current_names_take_precedence_over_stale_legacy_metadata(tmp_path):
    artifact, _, _ = legacy_archive(tmp_path / "old", 2)
    save_json(artifact.with_name(artifact.name + ".misong.json"), {"version": 99})
    with pytest.raises(ValueError, match="清单版本"):
        pack.unest(artifact, tmp_path / "restore", [])
    first, manifest = legacy_volumes(tmp_path / "volumes", bytes(range(256)))
    save_json(first.parent / "payload.zip.misongsplit.json", {**manifest, "source_sha256": "0" * 64})
    with pytest.raises(RuntimeError, match="整体 sha256"):
        split.join(first, tmp_path / "joined.zip")
    save_json(tmp_path / "nde-task.json", {"title": "stale"})
    save_json(tmp_path / "misong-task.json", {"title": "current"})
    assert workflows.read_meta(tmp_path)["title"] == "current"


def test_new_writers_only_create_misong_names(tmp_path):
    source = tmp_path / "source.bin"
    source.write_bytes(bytes(range(256)))
    output = tmp_path / "new" / "release.zip"
    pack.pack([source], [pack.LayerSpec("zip"), pack.LayerSpec(type="split", size="50B")], output)
    workflows.write_meta(output.parent, "pack", "new task")
    assert (output.parent / "release.zip.misong.json").is_file()
    assert (output.parent / "release.zip.misongsplit.json").is_file()
    assert (output.parent / "misong-task.json").is_file()
    assert not list(output.parent.glob("*.nde.json"))
    assert not list(output.parent.glob("*.ndesplit.json"))
    assert not (output.parent / "nde-task.json").exists()


@pytest.mark.parametrize("name", ["file.nde.json", "file.ndesplit.json", "nde-task.json",
                                  "file.misong.json", "file.misongsplit.json", "misong-task.json"])
def test_old_and_new_private_metadata_are_excluded_from_uploads(name):
    assert workflows.is_local_metadata(name)


@pytest.mark.parametrize("version", [1, 2])
def test_desktop_imports_old_manifest_and_preserves_task_fields(tmp_path, version):
    artifact, sidecar, _ = legacy_archive(tmp_path / "download", version)
    api = Api(runs_dir=tmp_path / "runs", state_dir=tmp_path / "state")
    result = api.import_task(str(artifact.parent))
    assert result["ok"] and result["data"]["kind"] == "pack"
    assert workflows.read_meta(artifact.parent)["artifact"] == str(artifact)
    assert sidecar.exists()
    current = artifact.parent / "misong-task.json"
    current.unlink()
    old = {"kind": "pack", "title": "old title", "created": "2026-10-01T12:00:00",
           "artifact": str(artifact), "chain": "zip", "note": "keep note"}
    save_json(artifact.parent / "nde-task.json", old)
    result = api.import_task(str(artifact.parent))
    assert result["ok"] and result["data"]["title"] == "old title"
    workflows.update_meta(artifact.parent, starred=True)
    updated = workflows.read_meta(artifact.parent)
    assert all(updated[key] == value for key, value in old.items())
    assert updated["starred"] is True and current.exists()
    assert json.loads((artifact.parent / "nde-task.json").read_text()) == old
    detail = api.task_detail(folder=str(artifact.parent))
    assert detail["ok"]
    assert not {"nde-task.json", "misong-task.json"} & {f["name"] for f in detail["data"]["files"]}


def test_old_checkpoint_keeps_remote_folder_and_skips_confirmed_upload(tmp_path):
    from test_publish import FakeRuntime
    folder = tmp_path / "old"
    folder.mkdir()
    files = [folder / "first.bin", folder / "second.bin"]
    for index, path in enumerate(files):
        path.write_bytes(bytes([index]) * 20)
    remote = "nde-existing-body-quark"
    plan = {"version": 2, "id": "old", "form": "direct", "state": "paused", "schemes": ["beast"],
            "stages": [{"id": "body", "role": "body", "disk": "quark", "folder": remote,
                        "files": [fingerprint(path) for path in files],
                        "uploaded": {str(files[0].resolve()): [remote]}, "state": "uploading"}]}
    path = folder / "relay-plan.json"
    save_json(path, plan)
    runtime = FakeRuntime()
    from misong.publish import publish
    result = asyncio.run(publish(path, runtime=runtime, notify=lambda _: None))
    assert runtime.payloads == {"second.bin": files[1].read_bytes()}
    assert result["plan"]["state"] == "complete"
    assert result["plan"]["stages"][0]["folder"] == remote


def test_existing_settings_templates_and_browser_choice_use_same_state_paths(tmp_path):
    assert ROOT == Path(__file__).resolve().parents[1]
    assert DEFAULT_STATE == ROOT / "rpa" / "state"
    state, output = tmp_path / "state", tmp_path / "prior-output"
    save_json(state / "ui-settings.json", {"output_dir": str(output), "output_roots": [str(output)]})
    template = {"name": "old template", "layers": [{"fmt": "zip", "locked": False}]}
    save_json(state / "ui-templates.json", {"seeded": True, "templates": [template]})
    save_json(state / "quark-browser.json", {"channel": "msedge"})
    before = {path.name: path.read_bytes() for path in state.iterdir()}
    api = Api(runs_dir=tmp_path / "runs", state_dir=state)
    assert api._runs == output.resolve()
    assert api._load_templates() == [template]
    runtime = api._runtime(lambda _: None)
    assert runtime.state_dir == state and runtime.browser_for("quark") == "msedge"
    assert before == {path.name: path.read_bytes() for path in state.iterdir()}


@pytest.mark.parametrize("scheme", ["beast", "hajimi", "mojibake"])
def test_fixed_pre_rename_share_copy_decodes_and_parses(tmp_path, capsys, scheme):
    if scheme == "mojibake" and not shutil.which("node"):
        pytest.skip("mojibake requires Node")
    from misong.sharing import parse_share
    fixture = json.loads((Path(__file__).parent / "fixtures" / "legacy-share-copy.json").read_text(encoding="utf-8"))
    cipher = tmp_path / "old-copy.txt"
    cipher.write_text(fixture[scheme], encoding="utf-8")
    assert main(["code", "decode", "-S", scheme, "-F", str(cipher), "--key", "compat-test-only"]) == 0
    text = capsys.readouterr().out.rstrip("\n")
    assert text == fixture["text"]
    share = parse_share(text, "quark", allowed_hosts=("example.invalid",))
    assert share.url == "https://example.invalid/s/legacy" and share.code == "A123"


@pytest.mark.parametrize("new_debug, expected", [(None, True), ("", False)])
def test_legacy_debug_variable_and_new_variable_precedence(monkeypatch, new_debug, expected):
    from misong.desktop import main as desktop
    monkeypatch.setenv("NDE_DEBUG", "1")
    monkeypatch.delenv("MISONG_DEBUG", raising=False)
    if new_debug is not None:
        monkeypatch.setenv("MISONG_DEBUG", new_debug)
    captured = {}
    class EventHook(list):
        def __iadd__(self, handler):
            self.append(handler)
            return self
    window = SimpleNamespace(events=SimpleNamespace(closing=EventHook()))
    api = SimpleNamespace(_attach=lambda _: None, _on_closing=lambda: None)
    monkeypatch.setattr(desktop, "Api", lambda: api)
    monkeypatch.setattr(desktop, "_dpi_aware", lambda: None)
    monkeypatch.setitem(sys.modules, "webview", SimpleNamespace(
        create_window=lambda *a, **kw: window,
        start=lambda *a, **kw: captured.update(kw)))
    assert desktop.main() == 0
    assert captured["debug"] is expected
